// Написан по плану и map-helpers.ts БЕЗ прогона на живой странице (MCP-генератор не нашёл seed) — проверить при первом /qa-regress.
// spec: .qa/e2e/specs/location-map.md
// seed: tests/seed.free.geo.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';
import { disableSharing } from './map-helpers';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free.json'),
  viewport: { width: 390, height: 844 },
  hasTouch: true,
  geolocation: { latitude: 32.0853, longitude: 34.7818, accuracy: 10 },
  permissions: ['geolocation'],
});

test.describe('Местоположение и карта', () => {
  test('Шаринг выключен — объяснение «שיתוף מיקום כבוי» и кнопка включения, приложение работает @iphone @data (#2a31ff)', async ({ page }) => {
    const shareWrites: string[] = [];
    page.on('request', (req) => {
      if (req.method() === 'PATCH' && req.url().includes('/rest/v1/profiles') && (req.postData() ?? '').includes('share_location')) {
        shareWrites.push(req.postData() ?? '');
      }
    });

    // 1. Открыть /map; если видна пилюля «שיתוף מיקום פעיל» — выключить шаринг (предусловие)
    await disableSharing(page);
    shareWrites.length = 0; // PATCH предусловия не считается

    // 2. Проверить карточку состояния
    await expect(page.getByText('שיתוף מיקום כבוי')).toBeVisible();
    await expect(page.getByText(/המיקום הנוכחי שלך יוצג במפה/)).toBeVisible();
    await expect(page.getByRole('button', { name: 'הפעלת שיתוף מיקום' }).or(page.getByText('הפעלת שיתוף מיקום')).first()).toBeVisible();

    // 3. Нажать вкладку «גילוי» в нижней навигации, затем «מפה»
    await page.getByText('גילוי', { exact: true }).last().click();
    await expect(page).toHaveURL(/\/discover/);
    await page.getByText('מפה', { exact: true }).last().click();
    await expect(page).toHaveURL(/\/map/);
    await expect(page.getByText('שיתוף מיקום כבוי')).toBeVisible();
    await expect(page.getByText(/המיקום הנוכחי שלך יוצג במפה/)).toBeVisible();

    // Кнопка не нажималась — записи share_location не было
    expect(shareWrites).toEqual([]);
  });
});
